import { httpResource } from '@angular/common/http';
import { Component } from '@angular/core';

interface Tarea {
  id: number;
  titulo: string;
}

@Component({
  selector: 'app-root',
  template: `
    <h1>Tareas</h1>
    @if (tareas.isLoading()) {
      <p>Cargando…</p>
    } @else if (tareas.error()) {
      <p>No pudimos cargar las tareas.</p>
      <button (click)="tareas.reload()">Reintentar</button>
    } @else {
      <ul>
        @for (t of tareas.value(); track t.id) {
          <li>{{ t.titulo }}</li>
        }
      </ul>
    }
  `,
})
export class App {
  protected readonly tareas = httpResource<Tarea[]>(() => 'api/tareas.json');
}
